def find_anagrams(s, p):
    n, m = len(s), len(p)
    result = []
    if m > n:
        return result

    need = [0] * 26
    window = [0] * 26
    for ch in p:
        need[ord(ch) - ord('a')] += 1
    for i in range(m):
        window[ord(s[i]) - ord('a')] += 1

    if window == need:
        result.append(0)

    for i in range(m, n):
        window[ord(s[i]) - ord('a')] += 1
        window[ord(s[i - m]) - ord('a')] -= 1
        if window == need:
            result.append(i - m + 1)

    return result

